Here's how to test `DataFetcher` with modern MSTest patterns:

```csharp
[TestClass]
public sealed class DataFetcherTests
{
    private readonly TestContext _testContext;
    private readonly MockHttpMessageHandler _handler;
    private readonly DataFetcher _fetcher;

    public DataFetcherTests(TestContext testContext)
    {
        _testContext = testContext;
        _handler = new MockHttpMessageHandler();
        _fetcher = new DataFetcher(new HttpClient(_handler));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_SuccessResponse_ReturnsContent()
    {
        // Arrange
        _handler.ResponseContent = "hello world";
        _handler.StatusCode = HttpStatusCode.OK;

        // Act
        var result = await _fetcher.FetchAsync(
            "https://example.com/data",
            _testContext.CancellationToken);

        // Assert
        Assert.AreEqual("hello world", result);
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_NotFound_ThrowsHttpRequestException()
    {
        _handler.StatusCode = HttpStatusCode.NotFound;

        await Assert.ThrowsExactlyAsync<HttpRequestException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/missing",
                _testContext.CancellationToken));
    }

    [TestMethod]
    [Timeout(5000)]
    public async Task FetchAsync_CancellationRequested_ThrowsOperationCanceled()
    {
        using var cts = CancellationTokenSource.CreateLinkedTokenSource(
            _testContext.CancellationToken);
        cts.Cancel();

        await Assert.ThrowsExactlyAsync<TaskCanceledException>(
            async () => await _fetcher.FetchAsync(
                "https://example.com/data", cts.Token));
    }

    // Minimal test double — avoids external mocking libraries
    private sealed class MockHttpMessageHandler : HttpMessageHandler
    {
        public HttpStatusCode StatusCode { get; set; } = HttpStatusCode.OK;
        public string ResponseContent { get; set; } = string.Empty;

        protected override Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request,
            CancellationToken cancellationToken)
        {
            cancellationToken.ThrowIfCancellationRequested();
            var response = new HttpResponseMessage(StatusCode)
            {
                Content = new StringContent(ResponseContent),
            };
            return Task.FromResult(response);
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | `async Task` return type — MSTest awaits them natively |
| **Timeouts** | `[Timeout(5000)]` auto-cancels via `TestContext.CancellationToken` |
| **Cooperative cancellation** | Pass `_testContext.CancellationToken` into every awaited call so timeouts actually abort work |
| **Cancellation testing** | `CreateLinkedTokenSource` links to the test's own token, then cancel immediately to verify the code honors cancellation |
| **Exception testing** | `Assert.ThrowsExactlyAsync` instead of `[ExpectedException]` — scoped, exact-type matching |
| **Constructor init** | Fields are `readonly`, `TestContext` injected via constructor (MSTest 3.6+) |
| **No mocking library needed** | A custom `HttpMessageHandler` is the idiomatic seam for `HttpClient` |
